package com.chatoverlay;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;

/**
 * Shared rendering utilities for all chat bubble overlays.
 *
 * <p>All methods are stateless with respect to per-frame render state; callers
 * supply colors, alpha, and positioning so this class has no per-message side effects.</p>
 */
@Singleton
public class BubbleRenderer
{
	public static final int BORDER_RADIUS = 12;
	private static final Color PEEK_AMBER = new Color(255, 200, 0, 220);

	private final ChatOverlayConfig config;

	@Inject
	public BubbleRenderer(ChatOverlayConfig config)
	{
		this.config = config;
	}

	// ── Font ────────────────────────────────────────────────────────────────

	public int getSnappedFontSize()
	{
		FontType type = config.fontType();
		boolean isRuneScape = type == FontType.RUNESCAPE
			|| type == FontType.RUNESCAPE_SMALL
			|| type == FontType.RUNESCAPE_BOLD;

		int currentSize = config.fontSize();
		if (isRuneScape)
		{
			Font nativeFont = resolveNativeFont();
			int nativeSize = nativeFont.getSize();
			int scale = Math.max(1, Math.round((float) currentSize / nativeSize));
			return nativeSize * scale;
		}
		return currentSize;
	}

	public Font resolveFont()
	{
		Font base;

		switch (config.fontType())
		{
			case RUNESCAPE:
				base = FontManager.getRunescapeFont();
				break;
			case RUNESCAPE_SMALL:
				base = FontManager.getRunescapeSmallFont();
				break;
			case RUNESCAPE_BOLD:
				base = FontManager.getRunescapeBoldFont();
				break;
			case ARIAL:
				base = new Font("Arial", Font.PLAIN, config.fontSize());
				break;
			case DIALOG:
				base = new Font(Font.DIALOG, Font.PLAIN, config.fontSize());
				break;
			case SANS_SERIF:
				base = new Font(Font.SANS_SERIF, Font.PLAIN, config.fontSize());
				break;
			case SERIF:
				base = new Font(Font.SERIF, Font.PLAIN, config.fontSize());
				break;
			case MONOSPACED:
				base = new Font(Font.MONOSPACED, Font.PLAIN, config.fontSize());
				break;
			case CUSTOM:
				base = new Font(config.customFontName(), Font.PLAIN, config.fontSize());
				break;
			default:
				base = FontManager.getRunescapeBoldFont();
				break;
		}
		return base.deriveFont((float) getSnappedFontSize());
	}

	public void configureRenderingHints(Graphics2D graphics)
	{
		FontType type = config.fontType();
		boolean isRuneScape = type == FontType.RUNESCAPE
			|| type == FontType.RUNESCAPE_SMALL
			|| type == FontType.RUNESCAPE_BOLD;

		if (isRuneScape)
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
		}
		else
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);
		}
	}

	// ── Alpha ────────────────────────────────────────────────────────────────

	/**
	 * Computes the message alpha based on its age, duration, and configurable fade-in and fade-out settings.
	 */
	public float computeAlpha(ChatLine line, long durMs, boolean fadeIn, boolean fadeOut)
	{
		if (durMs <= 0)
		{
			if (line.isPruned())
			{
				return Math.max(0f, 1.0f - (float) line.getPruneAge() / 1000f);
			}
			return 1.0f;
		}

		long ageMs = line.getAge();
		float baseAlpha = 1.0f;

		if (fadeIn)
		{
			long fadeInDurationMs = config.fadeInDuration() * 1000L;
			if (fadeInDurationMs > 0)
			{
				long fadeInEndMs = Math.min(fadeInDurationMs, durMs);
				if (ageMs < fadeInEndMs)
				{
					baseAlpha = (float) ageMs / fadeInEndMs;
				}
			}
		}

		if (fadeOut)
		{
			long fadeOutDurationMs = config.fadeOutDuration() * 1000L;
			if (fadeOutDurationMs > 0)
			{
				long fadeWindowMs = Math.min(fadeOutDurationMs, durMs);
				long fadeStartMs  = durMs - fadeWindowMs;
				if (ageMs >= fadeStartMs)
				{
					float fadeOutAlpha = Math.max(0f, 1.0f - (float) (ageMs - fadeStartMs) / fadeWindowMs);
					baseAlpha = Math.min(baseAlpha, fadeOutAlpha);
				}
			}
		}
		else
		{
			if (ageMs >= durMs)
			{
				baseAlpha = 0f;
			}
		}

		if (line.isPruned())
		{
			float pruneAlpha = Math.max(0f, 1.0f - (float) line.getPruneAge() / 1000f);
			return Math.min(baseAlpha, pruneAlpha);
		}
		return baseAlpha;
	}

	public List<ColorSegment> applyAlphaToSegments(List<ColorSegment> segments, float alpha)
	{
		List<ColorSegment> result = new ArrayList<>(segments.size());
		for (ColorSegment s : segments)
		{
			Color c = s.getColor();
			Color newColor = new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) (c.getAlpha() * alpha));
			if (s.getImage() != null)
			{
				result.add(new ColorSegment(s.getImage(), s.getImageId(), newColor));
			}
			else
			{
				result.add(new ColorSegment(s.getText(), newColor));
			}
		}
		return result;
	}

	// ── Drawing ──────────────────────────────────────────────────────────────

	/**
	 * Fills a rounded-rect bubble. {@code bg} alpha is scaled by {@code alpha}.
	 */
	public void drawBubble(Graphics2D graphics,
		int x, int y, int width, int height, Color bg, float alpha)
	{
		graphics.setColor(new Color(bg.getRed(), bg.getGreen(), bg.getBlue(),
			(int) (bg.getAlpha() * alpha)));
		int roundness = config.bubbleRoundness();
		graphics.fillRoundRect(x, y, width, height, roundness, roundness);
	}

	/**
	 * Draws a 1 px rounded border. When {@code isPeek} is true the border uses amber
	 * regardless of {@code borderColor}. Skips drawing when neither {@code showBorder}
	 * nor {@code isPeek} is true.
	 */
	public void drawBubbleBorder(Graphics2D graphics,
		int x, int y, int width, int height,
		Color borderColor, boolean showBorder, boolean isPeek, float alpha)
	{
		if (!showBorder && !isPeek)
		{
			return;
		}
		Color bc = isPeek ? PEEK_AMBER : borderColor;
		graphics.setColor(new Color(bc.getRed(), bc.getGreen(), bc.getBlue(),
			Math.min(255, (int) (bc.getAlpha() * alpha))));
		graphics.setStroke(new BasicStroke(1f));
		int roundness = config.bubbleRoundness();
		graphics.drawRoundRect(x, y, width - 1, height - 1, roundness, roundness);
	}

	// ── Text rendering ───────────────────────────────────────────────────────

	/**
	 * Renders color segments with the OSRS 1-pixel black drop shadow.
	 *
	 * @return x position after the last drawn character
	 */
	public Font resolveNativeFont()
	{
		switch (config.fontType())
		{
			case RUNESCAPE:       return FontManager.getRunescapeFont();
			case RUNESCAPE_SMALL: return FontManager.getRunescapeSmallFont();
			default:              return FontManager.getRunescapeBoldFont();
		}
	}

	public int renderSegments(Graphics2D graphics,
		List<ColorSegment> segments,
		int x, int y,
		FontMetrics fm,
		int maxX)
	{
		FontType type = config.fontType();
		boolean isRuneScape = type == FontType.RUNESCAPE
			|| type == FontType.RUNESCAPE_SMALL
			|| type == FontType.RUNESCAPE_BOLD;

		if (isRuneScape)
		{
			Font nativeFont = resolveNativeFont();
			int nativeSize = nativeFont.getSize();
			int currentSize = getSnappedFontSize();

			if (currentSize != nativeSize)
			{
				int scale = currentSize / nativeSize;
				FontMetrics nativeFm = graphics.getFontMetrics(nativeFont);
				int nativeW = getSegmentsWidth(segments, nativeFm);
				int nativeH = nativeFm.getHeight();

				if (nativeW <= 0 || nativeH <= 0)
				{
					return x;
				}

				java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
					nativeW + 4, nativeH + 4, java.awt.image.BufferedImage.TYPE_INT_ARGB);
				Graphics2D g2d = img.createGraphics();
				g2d.setFont(nativeFont);
				g2d.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
				g2d.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);

				// Render onto the image
				renderSegmentsDirectly(g2d, segments, 2, nativeFm.getAscent() + 2, nativeFm, nativeW + 4);
				g2d.dispose();

				// Scale and draw to main graphics context using integer factors
				int scaledW = (nativeW + 4) * scale;
				int scaledH = (nativeH + 4) * scale;
				int topY = y - nativeFm.getAscent() * scale;
				int drawX = x - 2 * scale;
				int drawY = topY - 2 * scale;

				Object oldInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
				graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
				graphics.drawImage(img, drawX, drawY, scaledW, scaledH, null);
				if (oldInterpolation != null)
				{
					graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
				}

				return x + nativeW * scale;
			}
		}

		return renderSegmentsDirectly(graphics, segments, x, y, fm, maxX);
	}

	private void drawBackgroundPass(Graphics2D graphics,
		List<ColorSegment> segments,
		int x, int y,
		FontMetrics fm,
		int maxX,
		int dx, int dy)
	{
		int passX = x;
		for (ColorSegment seg : segments)
		{
			if (passX >= maxX)
			{
				break;
			}
			if (seg.getImage() != null)
			{
				passX += seg.getImage().getWidth() + 2;
				continue;
			}
			String text = clipIfNeeded(seg.getText(), fm, maxX - passX);
			if (text.isEmpty())
			{
				break;
			}
			graphics.setColor(new Color(0, 0, 0, seg.getColor().getAlpha()));
			graphics.drawString(text, passX + dx, y + dy);
			passX += fm.stringWidth(text);
		}
	}

	private int renderSegmentsDirectly(Graphics2D graphics,
		List<ColorSegment> segments,
		int x, int y,
		FontMetrics fm,
		int maxX)
	{
		TextStyle style = config.textStyle();

		if (style == TextStyle.OUTLINE || style == TextStyle.OUTLINE_SHADOW)
		{
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, -1, 0);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 1, 0);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 0, -1);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 0, 1);

			if (config.fontType() != FontType.RUNESCAPE_SMALL)
			{
				drawBackgroundPass(graphics, segments, x, y, fm, maxX, -1, -1);
				drawBackgroundPass(graphics, segments, x, y, fm, maxX, 1, -1);
				drawBackgroundPass(graphics, segments, x, y, fm, maxX, -1, 1);
				drawBackgroundPass(graphics, segments, x, y, fm, maxX, 1, 1);
			}
		}

		if (style == TextStyle.SHADOW || style == TextStyle.OUTLINE_SHADOW)
		{
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 1, 1);
		}
		else if (style == TextStyle.SHADOW_BOLD)
		{
			// Better NPC Highlight "Debug NPC Info" outline-based text styling
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, -1, 0);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 1, 0);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 0, -1);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 0, 1);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 1, 1);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 1, 2);
			drawBackgroundPass(graphics, segments, x, y, fm, maxX, 2, 1);
		}

		// Main pass
		for (ColorSegment seg : segments)
		{
			if (x >= maxX)
			{
				break;
			}
			if (seg.getImage() != null)
			{
				java.awt.image.BufferedImage img = seg.getImage();
				int imgW = img.getWidth();
				int imgH = img.getHeight();
				if (x + imgW > maxX)
				{
					break;
				}
				int imgY = y - fm.getAscent() + (fm.getAscent() - imgH) / 2;
				float imgAlpha = seg.getColor().getAlpha() / 255.0f;
				Composite orig = graphics.getComposite();
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, imgAlpha));
				graphics.drawImage(img, x + 1, imgY, null);
				graphics.setComposite(orig);
				x += imgW + 2;
				continue;
			}
			String text = clipIfNeeded(seg.getText(), fm, maxX - x);
			if (text.isEmpty())
			{
				break;
			}
			graphics.setColor(seg.getColor());
			graphics.drawString(text, x, y);
			x += fm.stringWidth(text);
		}

		return x;
	}

	// ── Text layout ──────────────────────────────────────────────────────────

	public int getSegmentsWidth(List<ColorSegment> segments, FontMetrics fm)
	{
		int width = 0;
		for (ColorSegment seg : segments)
		{
			if (seg.getImage() != null)
			{
				width += seg.getImage().getWidth() + 2;
			}
			else
			{
				width += fm.stringWidth(seg.getText());
			}
		}
		return width;
	}

	public int getSlicedSegmentsWidth(List<ColorSegment> segments, int start, int end, FontMetrics fm)
	{
		List<ColorSegment> sliced = sliceSegments(segments, start, end);
		return getSegmentsWidth(sliced, fm);
	}

	/**
	 * Word wraps a list of color segments (which may contain inline images) by
	 * constructing a coordinate mapping of character offsets to custom segment/character widths.
	 */
	public List<int[]> wrapText(List<ColorSegment> segments, FontMetrics fm, int maxWidth)
	{
		List<Integer> charWidths = new ArrayList<>();
		StringBuilder sb = new StringBuilder();

		for (ColorSegment seg : segments)
		{
			if (seg.getImage() != null)
			{
				sb.append(' '); // Use space as 1-char placeholder
				charWidths.add(seg.getImage().getWidth() + 2);
			}
			else
			{
				String txt = seg.getText();
				for (int i = 0; i < txt.length(); i++)
				{
					sb.append(txt.charAt(i));
					charWidths.add(fm.charWidth(txt.charAt(i)));
				}
			}
		}

		String text = sb.toString();
		List<int[]> lines = new ArrayList<>();
		if (text.isEmpty())
		{
			return lines;
		}

		int totalW = 0;
		for (int w : charWidths)
		{
			totalW += w;
		}
		if (totalW <= maxWidth)
		{
			lines.add(new int[]{0, text.length()});
			return lines;
		}

		int lineStart = 0;
		int lastSpace = -1;
		int i         = lineStart;

		while (i < text.length())
		{
			if (text.charAt(i) == ' ')
			{
				lastSpace = i;
			}

			int curWidth = 0;
			for (int j = lineStart; j <= i; j++)
			{
				curWidth += charWidths.get(j);
			}

			if (curWidth > maxWidth)
			{
				if (lastSpace > lineStart)
				{
					lines.add(new int[]{lineStart, lastSpace});
					lineStart = lastSpace + 1;
					lastSpace = -1;
					i = lineStart;
				}
				else
				{
					int breakAt = i > lineStart ? i : i + 1;
					lines.add(new int[]{lineStart, breakAt});
					lineStart = breakAt;
					lastSpace = -1;
					i = lineStart;
				}
			}
			else
			{
				i++;
			}
		}

		if (lineStart < text.length())
		{
			lines.add(new int[]{lineStart, text.length()});
		}

		return lines;
	}

	/**
	 * Returns a list of [start, end) char ranges that fit within {@code maxWidth},
	 * breaking on word boundaries where possible.
	 */
	public List<int[]> wrapText(String text, FontMetrics fm, int maxWidth)
	{
		List<int[]> lines = new ArrayList<>();
		if (text.isEmpty())
		{
			return lines;
		}
		if (fm.stringWidth(text) <= maxWidth)
		{
			lines.add(new int[]{0, text.length()});
			return lines;
		}
		int lineStart = 0;
		int lastSpace = -1;
		int i         = lineStart;
		while (i < text.length())
		{
			if (text.charAt(i) == ' ')
			{
				lastSpace = i;
			}
			if (fm.stringWidth(text.substring(lineStart, i + 1)) > maxWidth)
			{
				if (lastSpace > lineStart)
				{
					lines.add(new int[]{lineStart, lastSpace});
					lineStart = lastSpace + 1;
					lastSpace = -1;
					i = lineStart;
				}
				else
				{
					int breakAt = i > lineStart ? i : i + 1;
					lines.add(new int[]{lineStart, breakAt});
					lineStart = breakAt;
					lastSpace = -1;
					i = lineStart;
				}
			}
			else
			{
				i++;
			}
		}
		if (lineStart < text.length())
		{
			lines.add(new int[]{lineStart, text.length()});
		}
		return lines;
	}

	/**
	 * Extracts the sub-segments covering chars [{@code start}, {@code end}) of the
	 * original plain string.
	 */
	public List<ColorSegment> sliceSegments(List<ColorSegment> segments, int start, int end)
	{
		List<ColorSegment> result = new ArrayList<>();
		int pos = 0;
		for (ColorSegment seg : segments)
		{
			String text = seg.getImage() != null ? " " : seg.getText();
			int    segEnd = pos + text.length();
			if (segEnd <= start)
			{
				pos = segEnd;
				continue;
			}
			if (pos >= end)
			{
				break;
			}
			int from = Math.max(0, start - pos);
			int to   = Math.min(text.length(), end - pos);
			if (from < to)
			{
				if (seg.getImage() != null)
				{
					result.add(seg);
				}
				else
				{
					result.add(new ColorSegment(text.substring(from, to), seg.getColor()));
				}
			}
			pos = segEnd;
		}
		return result;
	}

	public String clipIfNeeded(String text, FontMetrics fm, int availableWidth)
	{
		if (availableWidth <= 0)
		{
			return "";
		}
		if (fm.stringWidth(text) <= availableWidth)
		{
			return text;
		}
		String ellipsis = "...";
		int ew = fm.stringWidth(ellipsis);
		if (availableWidth <= ew)
		{
			return "";
		}
		for (int i = text.length() - 1; i > 0; i--)
		{
			if (fm.stringWidth(text.substring(0, i)) + ew <= availableWidth)
			{
				return text.substring(0, i) + ellipsis;
			}
		}
		return ellipsis;
	}
}

package com.chatoverlay;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.clan.ClanChannel;

/**
 * Resolves display names for the active clan channel, guest clan channel,
 * and friends chat channel, with safe fallback strings.
 */
@Singleton
public class ChannelNameResolver
{
	private final Client client;

	@Inject
	public ChannelNameResolver(Client client)
	{
		this.client = client;
	}

	public String getClanChannelName()
	{
		try
		{
			ClanChannel cc = client.getClanChannel();
			return cc != null ? cc.getName() : "Clan";
		}
		catch (Exception e)
		{
			return "Clan";
		}
	}

	public String getGuestClanChannelName()
	{
		try
		{
			ClanChannel cc = client.getGuestClanChannel();
			return cc != null ? cc.getName() : "Guest Clan";
		}
		catch (Exception e)
		{
			return "Guest Clan";
		}
	}

	public String getFriendsChatName()
	{
		try
		{
			FriendsChatManager fcm = client.getFriendsChatManager();
			return fcm != null ? fcm.getOwner() : "FC";
		}
		catch (Exception e)
		{
			return "FC";
		}
	}
}

package com.chatoverlay;

/**
 * Categories of chat messages for routing to the correct overlay.
 */
public enum ChatCategory
{
	PUBLIC,
	CLAN,
	FRIENDS_CHAT,
	PRIVATE,
	SYSTEM
}

package com.chatoverlay;

import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Varbits;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.config.ChatColorConfig;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.JagexColors;

/**
 * Resolves the correct {@link Color} for a given chat message type and color role,
 * honoring user-configured Chat Color plugin settings and falling back to OSRS defaults.
 */
@Singleton
public class ChatColorResolver
{
	private final Client        client;
	private final ConfigManager configManager;

	@Inject
	public ChatColorResolver(Client client, ConfigManager configManager)
	{
		this.client        = client;
		this.configManager = configManager;
	}

	public boolean isTransparentChatbox()
	{
		return isTransparentChatbox(client);
	}

	public static boolean isTransparentChatbox(Client client)
	{
		return client != null
			&& client.isResized()
			&& client.getVarbitValue(Varbits.TRANSPARENT_CHATBOX) == 1;
	}

	public ChatColorConfig getChatColorConfig()
	{
		return configManager.getConfig(ChatColorConfig.class);
	}

	/** Resolves the message-body or sender color for a given type. */
	public Color getChatColor(ChatMessageType type, ChatColorType colorType)
	{
		boolean t = isTransparentChatbox();
		ChatColorConfig cc = getChatColorConfig();

		Color color = resolveFromConfig(cc, type, colorType, t);
		if (color == null || color.getAlpha() == 0)
		{
			color = resolveJagexDefault(type, colorType, t);
		}
		return color;
	}

	/** Resolves the sender-name color, distinguishing the local player from others. */
	public Color getSenderColor(ChatMessageType type, ChatColorType colorType, boolean isSender)
	{
		boolean t = isTransparentChatbox();
		ChatColorConfig cc = getChatColorConfig();

		Color color = resolveSenderFromConfig(cc, type, colorType, t, isSender);
		if (color == null || color.getAlpha() == 0)
		{
			color = resolveJagexDefault(type, colorType, t);
		}
		return color;
	}

	/** Resolves the color for a channel-name prefix (e.g. "[Laced PVM] "). */
	public Color getChannelNameColor(ChatMessageType type)
	{
		boolean t = isTransparentChatbox();
		ChatColorConfig cc = getChatColorConfig();

		Color color;
		switch (type)
		{
			case CLAN_CHAT:
			case CLAN_GIM_CHAT:
			case CLAN_MESSAGE:
				color = t ? cc.transparentClanChannelName() : cc.opaqueClanChannelName();
				break;
			case CLAN_GUEST_CHAT:
			case CLAN_GUEST_MESSAGE:
				color = t ? cc.transparentClanChannelGuestName() : cc.opaqueClanGuestChatChannelName();
				break;
			case FRIENDSCHAT:
			case FRIENDSCHATNOTIFICATION:
				color = t ? cc.transparentFriendsChatChannelName() : cc.opaqueFriendsChatChannelName();
				break;
			default:
				color = null;
				break;
		}

		if (color == null || color.getAlpha() == 0)
		{
			color = t
				? JagexColors.CHAT_FC_NAME_TRANSPARENT_BACKGROUND
				: JagexColors.CHAT_FC_NAME_OPAQUE_BACKGROUND;
		}
		return color;
	}

	// ── Private helpers ───────────────────────────────────────────────────────

	private Color resolveFromConfig(
		ChatColorConfig cc, ChatMessageType type, ChatColorType colorType, boolean t)
	{
		switch (type)
		{
			case PUBLICCHAT:
			case MODCHAT:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentPublicChat()      : cc.opaquePublicChat())
					: (t ? cc.transparentUsername()        : cc.opaqueUsername());

			case AUTOTYPER:
			case MODAUTOTYPER:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentAutochatMessage() : cc.opaqueAutochatMessage())
					: (t ? cc.transparentUsername()        : cc.opaqueUsername());

			case CLAN_CHAT:
			case CLAN_GIM_CHAT:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentClanChatMessage()   : cc.opaqueClanChatMessage())
					: (t ? cc.transparentClanChatUsernames() : cc.opaqueClanChatUsernames());

			case CLAN_GUEST_CHAT:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentClanChatGuestMessage()   : cc.opaqueClanChatGuestMessage())
					: (t ? cc.transparentClanChatGuestUsernames() : cc.opaqueClanChatGuestUsernames());

			case CLAN_MESSAGE:
				return t ? cc.transparentClanChatInfo() : cc.opaqueClanChatInfo();

			case CLAN_GUEST_MESSAGE:
				return t ? cc.transparentClanChatGuestInfo() : cc.opaqueClanChatGuestInfo();

			case FRIENDSCHAT:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentFriendsChatMessage()   : cc.opaqueFriendsChatMessage())
					: (t ? cc.transparentFriendsChatUsernames() : cc.opaqueFriendsChatUsernames());

			case MODPRIVATECHAT:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentPrivateMessageReceived() : cc.opaquePrivateMessageReceived())
					: (t ? cc.transparentPrivateUsernames()       : cc.opaquePrivateUsernames());

			case PRIVATECHAT:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentPrivateMessageReceivedHighlight() : cc.opaquePrivateMessageReceivedHighlight())
					: (t ? cc.transparentPrivateMessageReceived()          : cc.opaquePrivateMessageReceived());

			case PRIVATECHATOUT:
				return colorType == ChatColorType.HIGHLIGHT
					? (t ? cc.transparentPrivateMessageSentHighlight() : cc.opaquePrivateMessageSentHighlight())
					: (t ? cc.transparentPrivateMessageSent()          : cc.opaquePrivateMessageSent());

			case GAMEMESSAGE:
			case ENGINE:
			case CONSOLE:
			case UNKNOWN:
				return t ? cc.transparentGameMessage() : cc.opaqueGameMessage();

			case SPAM:
				return t ? cc.transparentFiltered() : cc.opaqueFiltered();

			case BROADCAST:
				return t ? cc.transparentServerMessage() : cc.opaqueServerMessage();

			case FRIENDSCHATNOTIFICATION:
			case FRIENDNOTIFICATION:
			case LOGINLOGOUTNOTIFICATION:
				return t ? cc.transparentFriendsChatInfo() : cc.opaqueFriendsChatInfo();

			case WELCOME:
				return t ? cc.transparentServerMessage() : cc.opaqueServerMessage();

			case ITEM_EXAMINE:
			case NPC_EXAMINE:
			case OBJECT_EXAMINE:
				return t ? cc.transparentExamine() : cc.opaqueExamine();

			default:
				return null;
		}
	}

	private Color resolveSenderFromConfig(
		ChatColorConfig cc, ChatMessageType type, ChatColorType colorType, boolean t, boolean isSender)
	{
		if (isSender)
		{
			return t ? cc.transparentUsername() : cc.opaqueUsername();
		}
		switch (type)
		{
			case PUBLICCHAT:
				return t ? cc.transparentPlayerUsername() : cc.opaquePlayerUsername();

			case CLAN_CHAT:
			case CLAN_MESSAGE:
			case CLAN_GIM_CHAT:
				return t ? cc.transparentClanChatUsernames() : cc.opaqueClanChatUsernames();

			case CLAN_GUEST_CHAT:
			case CLAN_GUEST_MESSAGE:
				return t ? cc.transparentClanChatGuestUsernames() : cc.opaqueClanChatGuestUsernames();

			case FRIENDSCHATNOTIFICATION:
			case FRIENDSCHAT:
				return t ? cc.transparentFriendsChatUsernames() : cc.opaqueFriendsChatUsernames();

			case PRIVATECHAT:
			case PRIVATECHATOUT:
				return t ? cc.transparentPrivateUsernames() : cc.opaquePrivateUsernames();

			default:
				return t ? cc.transparentUsername() : cc.opaqueUsername();
		}
	}

	private Color resolveJagexDefault(ChatMessageType type, ChatColorType colorType, boolean t)
	{
		if (colorType == ChatColorType.NORMAL)
		{
			return Color.WHITE;
		}
		switch (type)
		{
			case PUBLICCHAT:
			case MODCHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
				return t ? JagexColors.CHAT_PUBLIC_TEXT_TRANSPARENT_BACKGROUND
				         : JagexColors.CHAT_PUBLIC_TEXT_OPAQUE_BACKGROUND;

			case PRIVATECHAT:
			case PRIVATECHATOUT:
			case MODPRIVATECHAT:
				return t ? JagexColors.CHAT_PRIVATE_MESSAGE_TEXT_TRANSPARENT_BACKGROUND
				         : JagexColors.CHAT_PRIVATE_MESSAGE_TEXT_OPAQUE_BACKGROUND;

			case CLAN_CHAT:
			case CLAN_GIM_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_MESSAGE:
			case CLAN_GUEST_MESSAGE:
			case FRIENDSCHAT:
			case FRIENDSCHATNOTIFICATION:
			case FRIENDNOTIFICATION:
				return t ? JagexColors.CHAT_FC_TEXT_TRANSPARENT_BACKGROUND
				         : JagexColors.CHAT_FC_TEXT_OPAQUE_BACKGROUND;

			default:
				return t ? JagexColors.CHAT_GAME_EXAMINE_TEXT_TRANSPARENT_BACKGROUND
				         : JagexColors.CHAT_GAME_EXAMINE_TEXT_OPAQUE_BACKGROUND;
		}
	}
}

package com.chatoverlay;

import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;

/**
 * Represents a single chat message captured from the game.
 *
 * <p>{@code rawMessage} and {@code rawSender} preserve OSRS {@code <col=RRGGBB>}
 * tags so overlays can render the exact colors from ChatColorPlugin or the server.
 * {@code channelName} carries the real clan/FC name (e.g. "Laced PVM") so the
 * overlay can display it instead of a generic "[Clan]" label.</p>
 *
 * <p>Colors are intentionally NOT stored here. Overlays resolve colors at render
 * time via {@link ChatOverlayPlugin#getChatColor} so they always reflect the
 * current transparency mode and the user's ChatColorPlugin settings.</p>
 */
public class ChatLine
{
	private final String sender;
	private final String rawSender;
	private final String rawMessage;
	private volatile long timestamp;
	private volatile int count = 1;
	private final ChatCategory category;
	private final ChatMessageType chatMessageType;
	private final MessageNode messageNode;

	private volatile String cachedRawMessage;
	private volatile String cachedPlainMessage;

	/** The clan or FC channel name (e.g. "Laced PVM"), or null for non-channel messages. */
	private final String channelName;

	private static final java.util.regex.Pattern CA_PREFIX_PATTERN =
		java.util.regex.Pattern.compile("(?i)CA(?:_ID)?\\s*:\\s*[^|]*\\|\\s*");

	private static final java.util.regex.Pattern BROADCAST_SUFFIX_PATTERN =
		java.util.regex.Pattern.compile("(?i)(?:\\|\\s*(?:\\d+|https?://\\S+|www\\.\\S+)\\s*)+((?:<[^>]+>)*\\s*)$");

	private static String cleanPrefixes(String msg)
	{
		if (msg == null)
		{
			return null;
		}
		String cleaned = CA_PREFIX_PATTERN.matcher(msg).replaceAll("");
		return BROADCAST_SUFFIX_PATTERN.matcher(cleaned).replaceAll("$1");
	}


	public ChatLine(
		MessageNode messageNode,
		String sender,
		String rawSender,
		String rawMessage,
		ChatCategory category,
		ChatMessageType chatMessageType,
		String channelName)
	{
		this.messageNode = messageNode;
		this.sender = sender == null ? "" : cleanPrefixes(sender);
		this.rawSender = rawSender == null ? "" : cleanPrefixes(rawSender);
		this.rawMessage = rawMessage == null ? "" : cleanPrefixes(rawMessage);
		this.timestamp = System.currentTimeMillis();
		this.category = category;
		this.chatMessageType = chatMessageType;
		this.channelName = channelName;

		String initialRaw = getRawMessage();
		this.cachedRawMessage = initialRaw;
		this.cachedPlainMessage = ColorTagParser.stripTags(initialRaw);
	}

	public ChatLine(
		MessageNode messageNode,
		String sender,
		String rawSender,
		String rawMessage,
		ChatCategory category,
		ChatMessageType chatMessageType)
	{
		this(messageNode, sender, rawSender, rawMessage, category, chatMessageType, null);
	}



	public String getSender()
	{
		return cleanPrefixes(sender);
	}

	public String getRawSender()
	{
		return cleanPrefixes(rawSender);
	}

	public String getRawMessage()
	{
		if (messageNode != null)
		{
			String rfmt = messageNode.getRuneLiteFormatMessage();
			String currentRaw = (rfmt != null && !rfmt.isEmpty()) ? rfmt : messageNode.getValue();
			if (currentRaw != null)
			{
				return cleanPrefixes(currentRaw);
			}
		}
		return rawMessage;
	}

	public String getPlainMessage()
	{
		String currentRaw = getRawMessage();
		if (currentRaw.equals(cachedRawMessage))
		{
			return cachedPlainMessage;
		}
		cachedRawMessage = currentRaw;
		cachedPlainMessage = ColorTagParser.stripTags(currentRaw);
		return cachedPlainMessage;
	}

	public long getTimestamp()
	{
		return timestamp;
	}

	public ChatCategory getCategory()
	{
		return category;
	}

	/**
	 * The RuneLite {@link ChatMessageType} for this line. Used by overlays to
	 * look up the correct color from {@link ChatOverlayPlugin#getChatColor}.
	 */
	public ChatMessageType getChatMessageType()
	{
		return chatMessageType;
	}

	/**
	 * The real channel name for clan/FC messages (e.g. "Laced PVM"),
	 * or {@code null} for public/private/system messages.
	 */
	public String getChannelName()
	{
		return channelName;
	}

	public long getAge()
	{
		return System.currentTimeMillis() - timestamp;
	}


	private volatile long pruneTimestamp = 0;

	public void prune()
	{
		if (pruneTimestamp == 0)
		{
			pruneTimestamp = System.currentTimeMillis();
		}
	}

	public boolean isPruned()
	{
		return pruneTimestamp > 0;
	}

	public int getCount()
	{
		return count;
	}

	public void setCount(int count)
	{
		this.count = count;
	}

	public void setTimestamp(long timestamp)
	{
		this.timestamp = timestamp;
	}

	public void updateTimestamp()
	{
		this.timestamp = System.currentTimeMillis();
	}

	public void resetPrune()
	{
		this.pruneTimestamp = 0;
	}

	public long getPruneTimestamp()
	{
		return pruneTimestamp;
	}

	public long getPruneAge()
	{
		return pruneTimestamp == 0 ? 0 : System.currentTimeMillis() - pruneTimestamp;
	}
}

package com.chatoverlay;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.client.config.ChatColorConfig;

/**
 * Stateful builder that converts raw OSRS chat markup into a flat list of
 * {@link ColorSegment}s ready for rendering.
 */
public class ChatLineBuilder
{
	private static final Pattern TAG_PATTERN = Pattern.compile(
		"<col=([0-9a-fA-F]{3,6})>"   // group 1: hex color
		+ "|</col>"                    // color end
		+ "|<col(NORMAL|HIGHLIGHT)>"   // group 2: named color
		+ "|<img=(\\d+)>"              // group 3: icon ID
		+ "|<br>"                      // line break → space
		+ "|<lt>"                      // entity: <
		+ "|<gt>"                      // entity: >
		+ "|<[^>]+>",                  // any other tag (stripped)
		Pattern.CASE_INSENSITIVE);

	@Getter
	private final List<ColorSegment> segments = new ArrayList<>();
	private final Color baseColor;
	private final ChatColorConfig chatColorConfig;
	private final Client client;

	public ChatLineBuilder(Client client, Color baseColor, ChatColorConfig chatColorConfig)
	{
		this.client = client;
		this.baseColor = baseColor;
		this.chatColorConfig = chatColorConfig;
	}

	/**
	 * Appends a string to the line
	 */
	public void append(String rawText)
	{
		append(rawText, this.baseColor);
	}

	/**
	 * Appends a string to the line
	 */
	public void append(String rawText, Color defaultColor)
	{
		if (rawText == null || rawText.isEmpty())
		{
			return;
		}

		rawText = ColorMacroResolver.resolve(client, rawText, ChatColorResolver.isTransparentChatbox(client));
		Matcher m = TAG_PATTERN.matcher(rawText);
		Color currentColor = defaultColor;
		int lastEnd = 0;

		while (m.find())
		{
			// Flush any plain text before this tag
			if (m.start() > lastEnd)
			{
				segments.add(new ColorSegment(
					rawText.substring(lastEnd, m.start()), currentColor));
			}

			String lowerMatch = m.group(0).toLowerCase();

			if (m.group(1) != null)
			{
				currentColor = hexToColor(m.group(1), defaultColor);
			}
			else if (lowerMatch.equals("</col>"))
			{
				currentColor = defaultColor;
			}
			else if (m.group(2) != null)
			{
				String name = m.group(2).toUpperCase();
				if ("NORMAL".equals(name))
				{
					currentColor = defaultColor;
				}
				else if ("HIGHLIGHT".equals(name))
				{
					Color highlight = null;
					if (chatColorConfig != null)
					{
						try
						{
							highlight = chatColorConfig.transparentExamineHighlight();
						}
						catch (Exception ignored) {}
					}
					currentColor = highlight != null ? highlight : defaultColor;
				}
			}
			else if (m.group(3) != null)
			{
				int imgId = -1;
				try
				{
					imgId = Integer.parseInt(m.group(3));
				}
				catch (NumberFormatException ignored) {}

				if (imgId >= 0 && client != null)
				{
					net.runelite.api.IndexedSprite[] modIcons = client.getModIcons();
					if (modIcons != null && imgId < modIcons.length && modIcons[imgId] != null)
					{
						BufferedImage img = PlayerIconLoader.toBufferedImage(modIcons[imgId]);
						segments.add(new ColorSegment(img, imgId));
					}
				}
			}
			else if (lowerMatch.equals("<lt>"))
			{
				segments.add(new ColorSegment("<", currentColor));
			}
			else if (lowerMatch.equals("<gt>"))
			{
				segments.add(new ColorSegment(">", currentColor));
			}
			else if (lowerMatch.equals("<br>"))
			{
				segments.add(new ColorSegment(" ", currentColor));
			}
			lastEnd = m.end();
		}

		// Flush any trailing plain text after the last tag
		if (lastEnd < rawText.length())
		{
			segments.add(new ColorSegment(
				rawText.substring(lastEnd), currentColor));
		}
	}

	/** Returns the plain text of the line by concatenating all segments. */
	public String toPlainString()
	{
		StringBuilder sb = new StringBuilder();
		for (ColorSegment segment : segments)
		{
			sb.append(segment.getText());
		}
		return sb.toString();
	}

	private static Color hexToColor(String hex, Color fallback)
	{
		if (hex == null)
		{
			return fallback;
		}
		try
		{
			if (hex.length() == 3)
			{
				char r = hex.charAt(0);
				char g = hex.charAt(1);
				char b = hex.charAt(2);
				hex = "" + r + r + g + g + b + b;
			}
			return Color.decode("#" + hex);
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}
}

package com.chatoverlay;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;

/**
 * Manages chat message queues for each overlay type, handling max-size limits
 * and time-based expiration for system alerts.
 */
public class ChatMessageManager
{
	private final LinkedList<ChatLine> publicClanMessages = new LinkedList<>();
	private final LinkedList<ChatLine> privateMessages = new LinkedList<>();
	private final LinkedList<ChatLine> systemMessages = new LinkedList<>();
	private final LinkedList<ChatLine> clanMessages = new LinkedList<>();

	/**
	 * Spam filter: tracks recently seen system messages to suppress duplicates.
	 * Key = lowercase message text, value = timestamp of last occurrence.
	 */
	private final Map<String, Long> recentSystemMessages = new LinkedHashMap<String, Long>()
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Long> eldest)
		{
			return size() > 50;
		}
	};

	private void pruneQueue(LinkedList<ChatLine> queue, int maxLimit)
	{
		long now = System.currentTimeMillis();
		// Remove messages that are pruned and fully faded out (1 second fade-out time)
		queue.removeIf(m -> m.isPruned() && (now - m.getPruneTimestamp()) > 1000L);

		int activeCount = 0;
		for (ChatLine m : queue)
		{
			if (!m.isPruned())
			{
				activeCount++;
			}
		}

		if (activeCount > maxLimit)
		{
			int toPrune = activeCount - maxLimit;
			for (ChatLine m : queue)
			{
				if (!m.isPruned())
				{
					m.prune();
					toPrune--;
					if (toPrune == 0)
					{
						break;
					}
				}
			}
		}
	}

	private List<ChatLine> getActiveAndFading(LinkedList<ChatLine> queue)
	{
		long now = System.currentTimeMillis();
		queue.removeIf(m -> m.isPruned() && (now - m.getPruneTimestamp()) > 1000L);
		return new ArrayList<>(queue);
	}

	private boolean isSameMessage(ChatLine m1, ChatLine m2, boolean isGameChat)
	{
		if (m1 == null || m2 == null)
		{
			return false;
		}

		String msg1 = m1.getPlainMessage() != null ? m1.getPlainMessage().trim() : "";
		String msg2 = m2.getPlainMessage() != null ? m2.getPlainMessage().trim() : "";

		if (!msg1.equalsIgnoreCase(msg2))
		{
			return false;
		}

		if (isGameChat)
		{
			return true;
		}

		String sender1 = m1.getSender() != null ? m1.getSender().trim() : "";
		String sender2 = m2.getSender() != null ? m2.getSender().trim() : "";

		if (!sender1.equalsIgnoreCase(sender2))
		{
			return false;
		}

		if (m1.getCategory() != m2.getCategory())
		{
			return false;
		}

		return java.util.Objects.equals(m1.getChannelName(), m2.getChannelName());
	}

	public void collapseQueue(LinkedList<ChatLine> queue, boolean isGameChat)
	{
		synchronized (queue)
		{
			if (queue.isEmpty())
			{
				return;
			}

			List<ChatLine> copy = new ArrayList<>(queue);
			queue.clear();

			for (ChatLine line : copy)
			{
				List<ChatLine> matches = new ArrayList<>();
				int existingCount = 0;
				for (ChatLine existing : queue)
				{
					if (isSameMessage(existing, line, isGameChat))
					{
						matches.add(existing);
						existingCount += existing.getCount();
					}
				}

				if (!matches.isEmpty())
				{
					line.setCount(existingCount + 1);
					queue.removeAll(matches);
				}
				else
				{
					line.setCount(1);
				}

				line.resetPrune();
				queue.addLast(line);
			}
		}
	}

	public void collapseSystemMessages()
	{
		collapseQueue(systemMessages, true);
		collapseQueue(publicClanMessages, true);
	}

	public void collapsePlayerMessages()
	{
		collapseQueue(publicClanMessages, false);
		collapseQueue(privateMessages, false);
		collapseQueue(clanMessages, false);
	}

	private void addMessageWithCollapsing(LinkedList<ChatLine> queue, ChatLine line, int maxLimit, boolean collapse, boolean isGameChat)
	{
		synchronized (queue)
		{
			if (collapse)
			{
				List<ChatLine> matches = new ArrayList<>();
				int existingCount = 0;
				for (ChatLine m : queue)
				{
					if (isSameMessage(m, line, isGameChat))
					{
						matches.add(m);
						existingCount += m.getCount();
					}
				}

				if (!matches.isEmpty())
				{
					line.setCount(existingCount + 1);
					queue.removeAll(matches);
				}
				else
				{
					line.setCount(1);
				}
			}
			else
			{
				line.setCount(1);
			}

			line.resetPrune();
			queue.addLast(line);
			pruneQueue(queue, maxLimit);
		}
	}

	public void addPublicClanMessage(ChatLine line, int maxMessages)
	{
		addPublicClanMessage(line, maxMessages, false);
	}

	public void addPublicClanMessage(ChatLine line, int maxMessages, boolean collapse)
	{
		boolean isGameChat = line.getCategory() == ChatCategory.SYSTEM;
		addMessageWithCollapsing(publicClanMessages, line, maxMessages, collapse, isGameChat);
	}

	public void addPrivateMessage(ChatLine line, int maxMessages)
	{
		addPrivateMessage(line, maxMessages, false);
	}

	public void addPrivateMessage(ChatLine line, int maxMessages, boolean collapse)
	{
		addMessageWithCollapsing(privateMessages, line, maxMessages, collapse, false);
	}

	public void addClanMessage(ChatLine line, int maxMessages)
	{
		addClanMessage(line, maxMessages, false);
	}

	public void addClanMessage(ChatLine line, int maxMessages, boolean collapse)
	{
		addMessageWithCollapsing(clanMessages, line, maxMessages, collapse, false);
	}

	public boolean addSystemMessage(ChatLine line, int maxAlerts, boolean filterSpam, long spamCooldownMs)
	{
		return addSystemMessage(line, maxAlerts, filterSpam, spamCooldownMs, false);
	}

	public boolean addSystemMessage(ChatLine line, int maxAlerts, boolean filterSpam, long spamCooldownMs, boolean collapse)
	{
		if (filterSpam && !collapse)
		{
			String lower = line.getPlainMessage().toLowerCase().trim();
			Long lastSeen = recentSystemMessages.get(lower);
			long now = System.currentTimeMillis();
			if (lastSeen != null && (now - lastSeen) < spamCooldownMs)
			{
				return false;
			}
			recentSystemMessages.put(lower, now);
		}

		addMessageWithCollapsing(systemMessages, line, maxAlerts, collapse, true);
		return true;
	}

	public List<ChatLine> getPublicClanMessages()
	{
		synchronized (publicClanMessages)
		{
			return getActiveAndFading(publicClanMessages);
		}
	}

	public List<ChatLine> getPrivateMessages()
	{
		synchronized (privateMessages)
		{
			return getActiveAndFading(privateMessages);
		}
	}

	public List<ChatLine> getSystemMessages()
	{
		synchronized (systemMessages)
		{
			return getActiveAndFading(systemMessages);
		}
	}

	public List<ChatLine> getClanMessages()
	{
		synchronized (clanMessages)
		{
			return getActiveAndFading(clanMessages);
		}
	}

	public void clearPublicClanMessages()
	{
		synchronized (publicClanMessages)
		{
			publicClanMessages.clear();
		}
	}

	public void clearPrivateMessages()
	{
		synchronized (privateMessages)
		{
			privateMessages.clear();
		}
	}

	public void clearClanMessages()
	{
		synchronized (clanMessages)
		{
			clanMessages.clear();
		}
	}

	public void clearSystemMessages()
	{
		synchronized (systemMessages)
		{
			systemMessages.clear();
		}
		recentSystemMessages.clear();
	}

	public void clearAll()
	{
		clearPublicClanMessages();
		clearPrivateMessages();
		clearSystemMessages();
		clearClanMessages();
	}
}

