import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Dedicated overlay for Clan, Guest Clan, GIM, and Friends Chat messages.
 */
public class ClanChatOverlay extends Overlay {
    private final Client client;
    private final ChatOverlayPlugin plugin;
    private final ChatOverlayConfig config;
    private final BubbleRenderer renderer;
    private final ChatColorResolver colorResolver;

    @Inject
    public ClanChatOverlay(Client client, ChatOverlayPlugin plugin, ChatOverlayConfig config,
                           BubbleRenderer renderer, ChatColorResolver colorResolver) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.renderer = renderer;
        this.colorResolver = colorResolver;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_LOW - 0.05f);
        setMovable(true);
        setSnappable(true);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showClanChatOverlay()) {
            return null;
        }
        if (config.clanHideWhenChatboxOpen() && plugin.isChatboxOpen()) {
            return null;
        }

        List<ChatLine> allMessages = plugin.getMessageManager().getClanMessages();
        List<ChatLine> messages = new java.util.ArrayList<>();
        for (ChatLine line : allMessages) {
            if (!plugin.shouldShowMessage(line)) {
                continue;
            }
            boolean keep = false;
            if (line.getCategory() == ChatCategory.FRIENDS_CHAT) {
                keep = config.clanShowFriendsChat();
            } else if (line.getCategory() == ChatCategory.CLAN) {
                net.runelite.api.ChatMessageType type = line.getChatMessageType();
                if (type == net.runelite.api.ChatMessageType.CLAN_GIM_CHAT) {
                    keep = config.clanShowGim();
                } else if (type == net.runelite.api.ChatMessageType.CLAN_GUEST_CHAT || type == net.runelite.api.ChatMessageType.CLAN_GUEST_MESSAGE) {
                    keep = config.clanShowGuest();
                } else {
                    keep = config.clanShowClan();
                }
            }
            if (keep) {
                messages.add(line);
            }
        }

        if (messages.isEmpty()) {
            return null;
        }

        int maxMsg = config.clanMaxMessages();
        if (messages.size() > maxMsg) {
            messages = messages.subList(messages.size() - maxMsg, messages.size());
        }

        renderer.configureRenderingHints(graphics);

        Font font = renderer.resolveFont();
        graphics.setFont(font);
        FontMetrics fm = graphics.getFontMetrics(font);

        int maxWidth = config.clanOverlayWidth();
        int maxHeight = config.clanOverlayHeight();
        LayoutMode layoutMode = config.clanLayoutMode();
        long durMs = config.clanMessageDuration() * 1000L;
        int paddingX = config.bubblePaddingX();
        int paddingY = config.bubblePaddingY();
        int bubbleSpacing = config.bubbleSpacing();

        int y = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? maxHeight : 0;
        int totalWidth = 0;

        int startIdx = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? messages.size() - 1 : 0;
        int endIdx = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? -1 : messages.size();
        int step = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? -1 : 1;

        for (int i = startIdx; i != endIdx; i += step) {
            ChatLine line = messages.get(i);
            float alpha = renderer.computeAlpha(line, durMs, config.clanFadeIn(), config.clanFadeOut());
            if (plugin.isPeekActive()) {
                alpha = 1.0f;
            }
            if (alpha <= 0.01f) {
                continue;
            }

            String localName = plugin.getLocalPlayerName();
            boolean isSender = localName != null && localName.equalsIgnoreCase(line.getRawSender());
            Color senderColor = colorResolver.getSenderColor(line.getChatMessageType(), ChatColorType.NORMAL, isSender);
            Color msgColor = colorResolver.getChatColor(line.getChatMessageType(), ChatColorType.HIGHLIGHT);

            Color customTimestampColor = config.clanTimestampColor() != null ? config.clanTimestampColor() : senderColor;
            Color customClanLabelColor = config.clanClanLabelColor() != null ? config.clanClanLabelColor() : colorResolver.getChannelNameColor(line.getChatMessageType());
            Color customUsernameColor  = config.clanUsernameColor() != null ? config.clanUsernameColor() : senderColor;
            Color customTextColor      = config.clanTextColor() != null ? config.clanTextColor() : msgColor;

            // Timestamp rendered separately: [timestamp] [icon] username
            String timestampStr = "";
            int timestampWidth = 0;
            if (config.clanShowTimestamp()) {
                LocalTime time = LocalTime.ofInstant(
                        Instant.ofEpochMilli(line.getTimestamp()), ZoneId.systemDefault());
                boolean showSeconds = config.timestampFormat() == TimestampFormat.HH_MM_SS;
                String formatStr = showSeconds ? "[%02d:%02d:%02d] " : "[%02d:%02d] ";
                if (showSeconds) {
                    timestampStr = String.format(formatStr, time.getHour(), time.getMinute(), time.getSecond());
                } else {
                    timestampStr = String.format(formatStr, time.getHour(), time.getMinute());
                }
                timestampWidth = fm.stringWidth(timestampStr);
            }

            ChatLineBuilder builder = new ChatLineBuilder(client, customTextColor, colorResolver.getChatColorConfig());
            String channelName = line.getChannelName();
            if (channelName != null && !channelName.isEmpty()) {
                builder.append("[" + channelName + "] ", customClanLabelColor);
            }
            if (!line.getSender().isEmpty()) {
                String senderName = config.showPlayerIcons() ? line.getRawSender() : line.getSender();
                builder.append(senderName, customUsernameColor);
                builder.append(": ");
            }
            builder.append(line.getRawMessage());
            if (line.getCount() > 1) {
                builder.append(" (" + line.getCount() + ")");
            }

            List<ColorSegment> allSegs = builder.getSegments();
            int innerWidth = maxWidth - paddingX * 2 - timestampWidth;
            List<ColorSegment> faded = renderer.applyAlphaToSegments(allSegs, alpha);

            int bubbleWidth;
            int bubbleHeight;

            if (config.publicWordWrap()) {
                List<int[]> lineRanges = renderer.wrapText(faded, fm, innerWidth);
                if (lineRanges.isEmpty()) {
                    continue;
                }
                int maxLineW = 0;
                for (int[] range : lineRanges) {
                    maxLineW = Math.max(maxLineW, renderer.getSlicedSegmentsWidth(faded, range[0], range[1], fm));
                }
                bubbleWidth = maxLineW + timestampWidth + paddingX * 2;
                bubbleHeight = fm.getHeight() * lineRanges.size() + paddingY * 2;

                int bubbleY;
                if (layoutMode == LayoutMode.BOTTOM_TO_TOP) {
                    y -= bubbleHeight;
                    if (y < 0) {
                        break;
                    }
                    bubbleY = y;
                } else {
                    if (y + bubbleHeight > maxHeight) {
                        break;
                    }
                    bubbleY = y;
                }

                boolean isHighlighted = !config.clanDisableKeywordHighlight() && plugin.shouldHighlight(line);
                Color bgColor = isHighlighted ? config.highlightBgColor() : config.clanBgColor();
                Color borderColor = isHighlighted ? config.highlightBorderColor() : config.clanBubbleBorderColor();
                boolean showBorder = isHighlighted ? config.highlightShowBorder() : config.clanShowBubbleBorder();

                if (isHighlighted || config.clanBgEnabled()) {
                    renderer.drawBubble(graphics, 0, bubbleY, bubbleWidth, bubbleHeight, bgColor, alpha);
                }
                renderer.drawBubbleBorder(graphics, 0, bubbleY, bubbleWidth, bubbleHeight,
                        borderColor, showBorder, plugin.isPeekActive(), alpha);

                int textY = bubbleY + paddingY + fm.getAscent();
                drawTimestamp(graphics, timestampStr, paddingX, textY, customTimestampColor, alpha);

                int startX = paddingX + timestampWidth;
                for (int[] range : lineRanges) {
                    List<ColorSegment> lineSegs = renderer.sliceSegments(faded, range[0], range[1]);
                    int lineW = renderer.getSlicedSegmentsWidth(faded, range[0], range[1], fm);
                    renderer.renderSegments(graphics, lineSegs, startX, textY, fm, startX + lineW);
                    textY += fm.getHeight();
                }
            } else {
                int textWidth = Math.min(renderer.getSegmentsWidth(faded, fm), innerWidth);
                bubbleWidth = textWidth + timestampWidth + paddingX * 2;
                bubbleHeight = fm.getHeight() + paddingY * 2;

                int bubbleY;
                if (layoutMode == LayoutMode.BOTTOM_TO_TOP) {
                    y -= bubbleHeight;
                    if (y < 0) {
                        break;
                    }
                    bubbleY = y;
                } else {
                    if (y + bubbleHeight > maxHeight) {
                        break;
                    }
                    bubbleY = y;
                }

                boolean isHighlighted = !config.clanDisableKeywordHighlight() && plugin.shouldHighlight(line);
                Color bgColor = isHighlighted ? config.highlightBgColor() : config.clanBgColor();
                Color borderColor = isHighlighted ? config.highlightBorderColor() : config.clanBubbleBorderColor();
                boolean showBorder = isHighlighted ? config.highlightShowBorder() : config.clanShowBubbleBorder();

                if (isHighlighted || config.clanBgEnabled()) {
                    renderer.drawBubble(graphics, 0, bubbleY, bubbleWidth, bubbleHeight, bgColor, alpha);
                }
                renderer.drawBubbleBorder(graphics, 0, bubbleY, bubbleWidth, bubbleHeight,
                        borderColor, showBorder, plugin.isPeekActive(), alpha);

                int textY = bubbleY + paddingY + fm.getAscent();
                drawTimestamp(graphics, timestampStr, paddingX, textY, customTimestampColor, alpha);

                int startX = paddingX + timestampWidth;
                renderer.renderSegments(graphics, faded, startX, textY, fm, startX + textWidth);
            }

            totalWidth = Math.max(totalWidth, bubbleWidth);

            if (layoutMode == LayoutMode.BOTTOM_TO_TOP) {
                y -= bubbleSpacing;
                if (y < 0) {
                    break;
                }
            } else {
                y += bubbleHeight + bubbleSpacing;
            }
        }

        if (layoutMode == LayoutMode.BOTTOM_TO_TOP) {
            if (y == maxHeight) {
                return null;
            }
            return new Dimension(Math.max(totalWidth, maxWidth), maxHeight);
        } else {
            if (y == 0) {
                return null;
            }
            return new Dimension(Math.max(totalWidth, maxWidth), y);
        }
    }

    // ── Helpers ──────────────────────────────────────────────────────────────

    private void drawTimestamp(Graphics2D graphics, String timestampStr, int x, int textY, Color tsColor, float alpha) {
        if (!timestampStr.isEmpty()) {
            Color tc = new Color(tsColor.getRed(), tsColor.getGreen(),
                    tsColor.getBlue(), (int) (tsColor.getAlpha() * alpha));
            Color black = new Color(0, 0, 0, tc.getAlpha());

            TextStyle style = config.textStyle();

            if (style == TextStyle.OUTLINE || style == TextStyle.OUTLINE_SHADOW) {
                graphics.setColor(black);
                graphics.drawString(timestampStr, x - 1, textY);
                graphics.drawString(timestampStr, x + 1, textY);
                graphics.drawString(timestampStr, x, textY - 1);
                graphics.drawString(timestampStr, x, textY + 1);
                graphics.drawString(timestampStr, x - 1, textY - 1);
                graphics.drawString(timestampStr, x + 1, textY - 1);
                graphics.drawString(timestampStr, x - 1, textY + 1);
                graphics.drawString(timestampStr, x + 1, textY + 1);
            }

            if (style == TextStyle.SHADOW || style == TextStyle.OUTLINE_SHADOW) {
                graphics.setColor(black);
                graphics.drawString(timestampStr, x + 1, textY + 1);
            } else if (style == TextStyle.SHADOW_BOLD) {
                graphics.setColor(black);
                graphics.drawString(timestampStr, x - 1, textY);
                graphics.drawString(timestampStr, x + 1, textY);
                graphics.drawString(timestampStr, x, textY - 1);
                graphics.drawString(timestampStr, x, textY + 1);
                graphics.drawString(timestampStr, x + 1, textY + 1);
                graphics.drawString(timestampStr, x + 1, textY + 2);
                graphics.drawString(timestampStr, x + 2, textY + 1);
            }

            graphics.setColor(tc);
            graphics.drawString(timestampStr, x, textY);
        }
    }
}

package com.chatoverlay;

import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import net.runelite.api.Client;

/**
 * Converts color macros emitted by the game into the {@code <col=RRGGBB>}
 * markup understood by {@link ChatLineBuilder}, and strips unmapped macro tags.
 */
public class ColorMacroResolver
{
	private static final Pattern MACRO_PATTERN = Pattern.compile(
		"@" + "([a-z0-9_]+)" + "@",
		Pattern.CASE_INSENSITIVE);
	private static final Map<String, MacroColor> MACRO_COLORS = Map.ofEntries(
		Map.entry("mes_hl_red", new MacroColor("e00a19", "ff3045")),
		Map.entry("mes_hl_gre", new MacroColor("06600c", "229628")),
		Map.entry("mes_hl_pur", new MacroColor("6800bf", "a53fff")),
		Map.entry("mes_hl_mag", new MacroColor("ef0083", "ff289d")),
		Map.entry("mes_hl_blu", new MacroColor("0000b2", "3366ff")),
		Map.entry("mes_hl_cya", new MacroColor("00ffff", "00e6e6")),
		Map.entry("mes_hl_ora", new MacroColor("b25000", "ff8e32"))
	);

	private ColorMacroResolver() {}

	/**
	 * Resolves color macros using {@link Client#macroExpand(String)} if available,
	 * followed by custom macro resolution and stripping of unmapped game macros.
	 */
	public static String resolve(Client client, String rawText, boolean isTransparent)
	{
		if (rawText == null || rawText.isEmpty())
		{
			return rawText;
		}

		if (client != null)
		{
			try
			{
				rawText = client.macroExpand(rawText);
			}
			catch (Throwable ignored)
			{
			}
		}

		return resolve(rawText, isTransparent);
	}

	/**
	 * Resolves known color macros and strips unmapped macro tags.
	 */
	public static String resolve(String rawText, boolean isTransparent)
	{
		if (rawText == null || rawText.isEmpty())
		{
			return rawText;
		}

		Matcher matcher = MACRO_PATTERN.matcher(rawText);
		StringBuffer resolved = new StringBuffer(rawText.length());
		while (matcher.find())
		{
			String name = matcher.group(1).toLowerCase();
			MacroColor color = MACRO_COLORS.get(name);
			String replacement = "";
			if (color != null)
			{
				String colorCode = isTransparent ? color.getTransparent() : color.getOpaque();
				replacement = "<col=" + colorCode + ">";
			}
			matcher.appendReplacement(resolved, replacement);
		}
		matcher.appendTail(resolved);
		return resolved.toString();
	}
}

package com.chatoverlay;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * A run of plain text paired with the color it should be drawn in,
 * or an inline image segment.
 * Produced by {@link ColorTagParser}.
 */
public class ColorSegment
{
	private final String text;
	private final Color color;
	private final BufferedImage image;
	private final int imageId;

	public ColorSegment(String text, Color color)
	{
		this.text = text;
		this.color = color;
		this.image = null;
		this.imageId = -1;
	}

	public ColorSegment(BufferedImage image, int imageId)
	{
		this(image, imageId, Color.WHITE);
	}

	public ColorSegment(BufferedImage image, int imageId, Color color)
	{
		this.text = "";
		this.color = color;
		this.image = image;
		this.imageId = imageId;
	}

	public String getText()
	{
		return text;
	}

	public Color getColor()
	{
		return color;
	}

	public BufferedImage getImage()
	{
		return image;
	}

	public int getImageId()
	{
		return imageId;
	}
}

package com.chatoverlay;

import java.util.regex.Pattern;

/**
 * A utility class for handling OSRS/RuneLite color tags.
 *
 * <p>The primary function of this class is to {@link #stripTags(String)},
 * which removes all {@code <col=...>}, {@code @macro@}, and other tags
 * from a string, returning only the plain text.</p>
 */
public class ColorTagParser
{
	private static final Pattern ANY_TAG = Pattern.compile(
		"<[^>]+>"                 // color tags
		+ "|@[a-z0-9_]+@",        // all macro tags
		Pattern.CASE_INSENSITIVE);

	private ColorTagParser() {}

	/** Strip all tags and return plain text. */
	public static String stripTags(String rawText)
	{
		if (rawText == null)
		{
			return "";
		}
		return ANY_TAG.matcher(rawText).replaceAll("");
	}
}

package com.chatoverlay;

/**
 * Matches comma-separated filter patterns against messages.
 *
 * <p>Per-pattern rules (case-insensitive):
 * <ul>
 *   <li>Pattern contains {@code *} anywhere — wildcard match: {@code *} matches any sequence of
 *       characters (including none). e.g. {@code spam*}, {@code *spam}, {@code *spam*}.</li>
 *   <li>Otherwise — substring match: the message must <em>contain</em> the pattern.</li>
 * </ul>
 */
public class FilterMatcher
{
	private static final String[] INTERACTION_SPAM_PATTERNS = {
		"you can't reach that",
		"i can't reach that",
		"nothing interesting happens",
		"you can't do that right now",
		"please finish what you're doing",
		"you need to be closer",
		"you can't use that here"
	};

	private static final String[] SKILLING_SPAM_PATTERNS = {
		"you swing your axe",
		"you get some * logs",
		"you get some * ore",
		"you swing your pick",
		"you manage to mine",
		"you catch a",
		"you net a",
		"you harpoon",
		"you successfully cook",
		"you accidentally burn",
		"the fire catches",
		"you plant the seed",
		"you treat the patch",
		"you bind the",
		"you craft the"
	};

	private static final String[] COMBAT_LOOT_SPAM_PATTERNS = {
		"your ring of wealth",
		"you find some coins",
		"you retrieve your ammo",
		"you drop the",
		"you construct a"
	};

	private static final String[] CONSUMABLES_SPAM_PATTERNS = {
		"you eat the",
		"you drink the",
		"it heals some health",
		"you restore some",
		"you drink some of your"
	};

	public boolean matchesInteraction(String lowerMessage)
	{
		return matchesAny(INTERACTION_SPAM_PATTERNS, lowerMessage);
	}

	public boolean matchesSkilling(String lowerMessage)
	{
		return matchesAny(SKILLING_SPAM_PATTERNS, lowerMessage);
	}

	public boolean matchesCombatLoot(String lowerMessage)
	{
		return matchesAny(COMBAT_LOOT_SPAM_PATTERNS, lowerMessage);
	}

	public boolean matchesConsumables(String lowerMessage)
	{
		return matchesAny(CONSUMABLES_SPAM_PATTERNS, lowerMessage);
	}

	private boolean matchesAny(String[] patterns, String lowerMessage)
	{
		for (String pattern : patterns)
		{
			if (pattern.contains("*"))
			{
				if (wildcardMatches(pattern, lowerMessage))
				{
					return true;
				}
			}
			else
			{
				if (lowerMessage.contains(pattern))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Returns true if {@code lowerMessage} matches any pattern in {@code rawPatterns}.
	 *
	 * @param rawPatterns  comma-separated pattern string from config
	 * @param lowerMessage the plain message text, already lowercased by the caller
	 */
	public boolean matches(String rawPatterns, String lowerMessage)
	{
		if (rawPatterns == null || rawPatterns.trim().isEmpty())
		{
			return false;
		}
		for (String part : rawPatterns.split(","))
		{
			String pattern = part.trim().toLowerCase();
			if (pattern.isEmpty())
			{
				continue;
			}
			if (pattern.contains("*"))
			{
				if (wildcardMatches(pattern, lowerMessage))
				{
					return true;
				}
			}
			else
			{
				if (lowerMessage.contains(pattern))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Matches {@code text} against a wildcard {@code pattern} where {@code *} matches any sequence.
	 * Both arguments must already be lowercased.
	 */
	private static boolean wildcardMatches(String pattern, String text)
	{
		String[] parts = pattern.split("\\*", -1);
		int pos = 0;
		for (int i = 0; i < parts.length; i++)
		{
			String part = parts[i];
			if (i == 0)
			{
				// First segment must match at the start (no leading wildcard)
				if (!text.startsWith(part))
				{
					return false;
				}
				pos = part.length();
			}
			else if (i == parts.length - 1)
			{
				// Last segment must match at the end
				if (part.isEmpty())
				{
					// trailing * — anything goes
					break;
				}
				if (!text.endsWith(part) || text.length() - part.length() < pos)
				{
					return false;
				}
			}
			else
			{
				// Middle segment: find next occurrence at or after pos
				int idx = text.indexOf(part, pos);
				if (idx < 0)
				{
					return false;
				}
				pos = idx + part.length();
			}
		}
		return true;
	}
}

