package com.chatoverlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.time.Instant;
import java.time.LocalTime;
import java.time.ZoneId;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.config.ChatColorConfig;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * System/game message alert overlay.
 */
public class GameOverlay extends Overlay
{
	private final Client            client;
	private final ChatOverlayPlugin plugin;
	private final ChatOverlayConfig config;
	private final BubbleRenderer    renderer;
	private final ChatColorResolver colorResolver;

	@Inject
	public GameOverlay(Client client, ChatOverlayPlugin plugin, ChatOverlayConfig config,
		BubbleRenderer renderer, ChatColorResolver colorResolver)
	{
		this.client        = client;
		this.plugin        = plugin;
		this.config        = config;
		this.renderer      = renderer;
		this.colorResolver = colorResolver;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_HIGH);
	}

	void prepareRegistration()
	{
		boolean floating = config.systemAlertMode() == GameOverlayMode.OVERLAY;
		setPosition(floating ? OverlayPosition.TOP_LEFT : OverlayPosition.DYNAMIC);
		setLayer(floating && !config.drawBelowInterfaces() ? OverlayLayer.ABOVE_WIDGETS : OverlayLayer.ABOVE_SCENE);
		// RuneLite would clear saved floating placement when loading a non-movable overlay.
		setMovable(true);
		setSnappable(true);
	}

	void finishRegistration()
	{
		if (config.systemAlertMode() == GameOverlayMode.PINNED_TO_PLAYER)
		{
			setMovable(false);
			setSnappable(false);
			setPreferredLocation(null);
			setPreferredSize(null);
			setPreferredPosition(null);
			getBounds().setBounds(0, 0, 0, 0);
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showSystemAlerts())
		{
			return null;
		}
		if (config.systemHideWhenChatboxOpen() && plugin.isChatboxOpen())
		{
			return null;
		}

		List<ChatLine> allAlerts = plugin.getMessageManager().getSystemMessages();
		List<ChatLine> alerts = new java.util.ArrayList<>();
		for (ChatLine alert : allAlerts)
		{
			if (!plugin.shouldShowMessage(alert))
			{
				continue;
			}
			if (config.filterSystemConsole() &&
				(alert.getChatMessageType() == net.runelite.api.ChatMessageType.CONSOLE ||
				 alert.getChatMessageType() == net.runelite.api.ChatMessageType.UNKNOWN))
			{
				continue;
			}
			if (!plugin.isSystemMessageFiltered(alert.getPlainMessage().toLowerCase()))
			{
				alerts.add(alert);
			}
		}

		if (alerts.isEmpty())
		{
			return null;
		}

		int maxAlerts = config.systemMaxAlerts();
		int activeCount = 0;
		for (ChatLine alert : alerts)
		{
			if (!alert.isPruned())
			{
				activeCount++;
			}
		}

		if (activeCount > maxAlerts)
		{
			int toPrune = activeCount - maxAlerts;
			for (ChatLine alert : alerts)
			{
				if (!alert.isPruned())
				{
					alert.prune();
					toPrune--;
					if (toPrune == 0)
					{
						break;
					}
				}
			}
		}

		GameOverlayMode mode = config.systemAlertMode();

		renderer.configureRenderingHints(graphics);
		Font font = renderer.resolveFont();
		graphics.setFont(font);
		FontMetrics fm = graphics.getFontMetrics(font);
		long durationMs = config.systemAlertDuration() * 1000L;

		return mode == GameOverlayMode.OVERLAY
			? renderAsOverlay(graphics, alerts, fm, durationMs)
			: renderPinnedToPlayer(graphics, alerts, fm, durationMs);
	}

	// ── Pinned-to-Player mode ───────────────────────────────────────────────

	private Dimension renderPinnedToPlayer(
		Graphics2D graphics, List<ChatLine> alerts, FontMetrics fm, long durationMs)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return null;
		}
		Point anchor = localPlayer.getCanvasTextLocation(
			graphics, "X", localPlayer.getLogicalHeight() + config.systemPlayerOffset());
		if (anchor == null)
		{
			return null;
		}

		int paddingX      = config.bubblePaddingX();
		int paddingY      = config.bubblePaddingY();
		int bubbleSpacing = config.bubbleSpacing();

		java.awt.geom.AffineTransform tx = graphics.getTransform();
		int centerX  = anchor.getX() - (int) tx.getTranslateX();
		int currentY = anchor.getY() - (int) tx.getTranslateY();

		LayoutMode layoutMode = config.systemLayoutMode();

		for (int i = alerts.size() - 1; i >= 0; i--)
		{
			ChatLine alert = alerts.get(i);
			float alpha = renderer.computeAlpha(alert, durationMs, config.systemFadeIn(), config.systemFadeOut());
			if (plugin.isPeekActive())
			{
				alpha = 1.0f;
			}
			if (alpha <= 0.01f)
			{
				continue;
			}

			AlertContent ac   = buildAlert(alert, alpha);
			String plain      = ac.plain;
			List<ColorSegment> faded = ac.faded;
			int    maxWidth   = config.systemOverlayWidth();
			int    innerWidth = maxWidth - paddingX * 2;

			int bubbleWidth;
			int bubbleHeight;

			if (config.systemWordWrap())
			{
				List<int[]> lineRanges = renderer.wrapText(faded, fm, innerWidth);
				if (lineRanges.isEmpty())
				{
					continue;
				}
				int maxLineW = 0;
				for (int[] range : lineRanges)
				{
					maxLineW = Math.max(maxLineW, renderer.getSlicedSegmentsWidth(faded, range[0], range[1], fm));
				}
				bubbleWidth  = maxLineW + paddingX * 2;
				bubbleHeight = fm.getHeight() * lineRanges.size() + paddingY * 2;
				int bubbleX  = centerX - bubbleWidth / 2;

				int bubbleY;
				if (layoutMode == LayoutMode.BOTTOM_TO_TOP)
				{
					bubbleY = currentY - bubbleHeight;
					currentY = bubbleY - bubbleSpacing;
				}
				else
				{
					bubbleY = currentY;
					currentY = bubbleY + bubbleHeight + bubbleSpacing;
				}

				boolean isHighlighted = !config.systemDisableKeywordHighlight() && plugin.shouldHighlight(alert);
				Color bgColor = isHighlighted ? config.highlightBgColor() : config.systemBgColor();
				Color borderColor = isHighlighted ? config.highlightBorderColor() : config.systemBubbleBorderColor();
				boolean showBorder = isHighlighted ? config.highlightShowBorder() : config.systemShowBubbleBorder();

				renderer.drawBubble(graphics, bubbleX, bubbleY, bubbleWidth, bubbleHeight, bgColor, alpha);
				renderer.drawBubbleBorder(graphics, bubbleX, bubbleY, bubbleWidth, bubbleHeight,
					borderColor, showBorder, plugin.isPeekActive(), alpha);

				int textY = bubbleY + paddingY + fm.getAscent();
				for (int[] range : lineRanges)
				{
					List<ColorSegment> lineSegs = renderer.sliceSegments(faded, range[0], range[1]);
					int lineW      = renderer.getSlicedSegmentsWidth(faded, range[0], range[1], fm);
					int textStartX = centerX - lineW / 2;
					renderer.renderSegments(graphics, lineSegs, textStartX, textY, fm, textStartX + lineW);
					textY += fm.getHeight();
				}
			}
			else
			{
				int textWidth = Math.min(renderer.getSegmentsWidth(faded, fm), innerWidth);
				bubbleWidth  = textWidth + paddingX * 2;
				bubbleHeight = fm.getHeight() + paddingY * 2;
				int bubbleX  = centerX - bubbleWidth / 2;

				int bubbleY;
				if (layoutMode == LayoutMode.BOTTOM_TO_TOP)
				{
					bubbleY = currentY - bubbleHeight;
					currentY = bubbleY - bubbleSpacing;
				}
				else
				{
					bubbleY = currentY;
					currentY = bubbleY + bubbleHeight + bubbleSpacing;
				}

				boolean isHighlighted = !config.systemDisableKeywordHighlight() && plugin.shouldHighlight(alert);
				Color bgColor = isHighlighted ? config.highlightBgColor() : config.systemBgColor();
				Color borderColor = isHighlighted ? config.highlightBorderColor() : config.systemBubbleBorderColor();
				boolean showBorder = isHighlighted ? config.highlightShowBorder() : config.systemShowBubbleBorder();

				renderer.drawBubble(graphics, bubbleX, bubbleY, bubbleWidth, bubbleHeight, bgColor, alpha);
				renderer.drawBubbleBorder(graphics, bubbleX, bubbleY, bubbleWidth, bubbleHeight,
					borderColor, showBorder, plugin.isPeekActive(), alpha);

				int textY      = bubbleY + paddingY + fm.getAscent();
				int textStartX = centerX - textWidth / 2;
				renderer.renderSegments(graphics, faded, textStartX, textY, fm, textStartX + textWidth);
			}
		}

		return null; // DYNAMIC overlays don't return a bounding Dimension
	}

	// ── Free-Overlay mode ───────────────────────────────────────────────────

	private Dimension renderAsOverlay(
		Graphics2D graphics, List<ChatLine> alerts, FontMetrics fm, long durationMs)
	{
		int paddingX      = config.bubblePaddingX();
		int paddingY      = config.bubblePaddingY();
		int bubbleSpacing = config.bubbleSpacing();

		int maxWidth      = config.systemOverlayWidth();
		int maxHeight     = config.systemOverlayHeight();

		LayoutMode layoutMode = config.systemLayoutMode();
		int y          = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? maxHeight : 0;
		int totalWidth = 0;

		int startIdx = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? 0 : alerts.size() - 1;
		int endIdx   = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? alerts.size() : -1;
		int step     = (layoutMode == LayoutMode.BOTTOM_TO_TOP) ? 1 : -1;

		for (int i = startIdx; i != endIdx; i += step)
		{
			ChatLine alert = alerts.get(i);
			float alpha = renderer.computeAlpha(alert, durationMs, config.systemFadeIn(), config.systemFadeOut());
			if (plugin.isPeekActive())
			{
				alpha = 1.0f;
			}
			if (alpha <= 0.01f)
			{
				continue;
			}

			AlertContent ac   = buildAlert(alert, alpha);
			String plain      = ac.plain;
			List<ColorSegment> faded = ac.faded;
			int    innerWidth = maxWidth - paddingX * 2;

			int bubbleWidth;
			int bubbleHeight;

			if (config.systemWordWrap())
			{
				List<int[]> lineRanges = renderer.wrapText(faded, fm, innerWidth);
				if (lineRanges.isEmpty())
				{
					continue;
				}
				int maxLineW = 0;
				for (int[] range : lineRanges)
				{
					maxLineW = Math.max(maxLineW, renderer.getSlicedSegmentsWidth(faded, range[0], range[1], fm));
				}
				bubbleWidth  = maxLineW + paddingX * 2;
				bubbleHeight = fm.getHeight() * lineRanges.size() + paddingY * 2;

				int bubbleY;
				if (layoutMode == LayoutMode.BOTTOM_TO_TOP)
				{
					y -= bubbleHeight;
					if (y < 0)
					{
						break;
					}
					bubbleY = y;
				}
				else
				{
					if (y + bubbleHeight > maxHeight)
					{
						break;
					}
					bubbleY = y;
				}

				boolean isHighlighted = !config.systemDisableKeywordHighlight() && plugin.shouldHighlight(alert);
				Color bgColor = isHighlighted ? config.highlightBgColor() : config.systemBgColor();
				Color borderColor = isHighlighted ? config.highlightBorderColor() : config.systemBubbleBorderColor();
				boolean showBorder = isHighlighted ? config.highlightShowBorder() : config.systemShowBubbleBorder();

				renderer.drawBubble(graphics, 0, bubbleY, bubbleWidth, bubbleHeight, bgColor, alpha);
				renderer.drawBubbleBorder(graphics, 0, bubbleY, bubbleWidth, bubbleHeight,
					borderColor, showBorder, plugin.isPeekActive(), alpha);

				int textY = bubbleY + paddingY + fm.getAscent();
				for (int[] range : lineRanges)
				{
					List<ColorSegment> lineSegs = renderer.sliceSegments(faded, range[0], range[1]);
					int lineW = renderer.getSlicedSegmentsWidth(faded, range[0], range[1], fm);
					renderer.renderSegments(graphics, lineSegs, paddingX, textY, fm, paddingX + lineW);
					textY += fm.getHeight();
				}
			}
			else
			{
				int textWidth = Math.min(renderer.getSegmentsWidth(faded, fm), innerWidth);
				bubbleWidth  = textWidth + paddingX * 2;
				bubbleHeight = fm.getHeight() + paddingY * 2;

				int bubbleY;
				if (layoutMode == LayoutMode.BOTTOM_TO_TOP)
				{
					y -= bubbleHeight;
					if (y < 0)
					{
						break;
					}
					bubbleY = y;
				}
				else
				{
					if (y + bubbleHeight > maxHeight)
					{
						break;
					}
					bubbleY = y;
				}

				boolean isHighlighted = !config.systemDisableKeywordHighlight() && plugin.shouldHighlight(alert);
				Color bgColor = isHighlighted ? config.highlightBgColor() : config.systemBgColor();
				Color borderColor = isHighlighted ? config.highlightBorderColor() : config.systemBubbleBorderColor();
				boolean showBorder = isHighlighted ? config.highlightShowBorder() : config.systemShowBubbleBorder();

				renderer.drawBubble(graphics, 0, bubbleY, bubbleWidth, bubbleHeight, bgColor, alpha);
				renderer.drawBubbleBorder(graphics, 0, bubbleY, bubbleWidth, bubbleHeight,
					borderColor, showBorder, plugin.isPeekActive(), alpha);

				int textY = bubbleY + paddingY + fm.getAscent();
				renderer.renderSegments(graphics, faded, paddingX, textY, fm, paddingX + textWidth);
			}

			totalWidth = Math.max(totalWidth, bubbleWidth);
			if (layoutMode == LayoutMode.BOTTOM_TO_TOP)
			{
				y -= bubbleSpacing;
				if (y < 0)
				{
					break;
				}
			}
			else
			{
				y += bubbleHeight + bubbleSpacing;
			}
		}

		if (layoutMode == LayoutMode.BOTTOM_TO_TOP)
		{
			if (y == maxHeight)
			{
				return null;
			}
			return new Dimension(Math.max(totalWidth, maxWidth), maxHeight);
		}
		else
		{
			if (y == 0)
			{
				return null;
			}
			return new Dimension(Math.max(totalWidth, maxWidth), y);
		}
	}

	// ── Helpers ──────────────────────────────────────────────────────────────

	static class AlertContent
	{
		final String            plain;
		final List<ColorSegment> faded;

		AlertContent(String plain, List<ColorSegment> faded)
		{
			this.plain = plain;
			this.faded = faded;
		}
	}

	/**
	 * Builds both the plain (tag-stripped) text and the alpha-faded segments for
	 * an alert from the same {@link ChatLineBuilder} pass, ensuring bubble sizing
	 * and rendering are always in sync.
	 */
	private AlertContent buildAlert(ChatLine alert, float alpha)
	{
		Color           msgColor = colorResolver.getChatColor(alert.getChatMessageType(), ChatColorType.HIGHLIGHT);
		Color           customTextColor = config.systemTextColor() != null ? config.systemTextColor() : msgColor;
		ChatLineBuilder builder  = new ChatLineBuilder(client, customTextColor, colorResolver.getChatColorConfig());
		if (config.systemShowTimestamp())
		{
			LocalTime time = LocalTime.ofInstant(
				Instant.ofEpochMilli(alert.getTimestamp()), ZoneId.systemDefault());
			boolean showSeconds = config.timestampFormat() == TimestampFormat.HH_MM_SS;
			String formatStr = showSeconds ? "[%02d:%02d:%02d] " : "[%02d:%02d] ";
			String timestampStr;
			if (showSeconds)
			{
				timestampStr = String.format(formatStr, time.getHour(), time.getMinute(), time.getSecond());
			}
			else
			{
				timestampStr = String.format(formatStr, time.getHour(), time.getMinute());
			}
			Color customTimestampColor = config.systemTimestampColor() != null ? config.systemTimestampColor() : msgColor;
			builder.append(timestampStr, customTimestampColor);
		}
		builder.append(alert.getRawMessage());
		if (alert.getCount() > 1)
		{
			builder.append(" (" + alert.getCount() + ")");
		}
		return new AlertContent(
			builder.toPlainString(),
			renderer.applyAlphaToSegments(builder.getSegments(), alpha));
	}
}

package com.chatoverlay;

/**
 * Display mode for the game overlay.
 *
 * <ul>
 *   <li>{@link #PINNED_TO_PLAYER} — bubbles float above the local player character
 *       (current classic behaviour).</li>
 *   <li>{@link #OVERLAY} — alerts render inside a free-floating panel that the
 *       player can drag anywhere on screen.</li>
 * </ul>
 */
public enum GameOverlayMode
{
	PINNED_TO_PLAYER("Pinned to Player"),
	OVERLAY("Free Overlay");

	private final String label;

	GameOverlayMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

